def diff(a,b,p=''):
 if type(a)!=type(b):return [{'path':p,'stored':a,'recomputed':b}]
 if isinstance(a,dict):
  return [d for k in sorted(a.keys()|b.keys()) for d in (diff(a[k],b[k],p+'/'+k) if k in a and k in b else [{'path':p+'/'+k,'stored':a.get(k),'recomputed':b.get(k)}])]
 if isinstance(a,list):
  if len(a)!=len(b):return [{'path':p,'stored_length':len(a),'recomputed_length':len(b)}]
  return [d for i,(x,y) in enumerate(zip(a,b)) for d in diff(x,y,p+'/'+str(i))]
 return [] if a==b else [{'path':p,'stored':a,'recomputed':b}]
