import ast, hashlib, json, pathlib, subprocess
from investigate import CASES
ROOT=pathlib.Path('<repo>'); OUT=pathlib.Path(__file__).parent
CASE_PATHS={
'27':'artifacts/grounding-v5-d58-design/memory-repair/sources.json',
'42':'artifacts/grounding-v5-d58-review-corrections/correction.json',
'43':'artifacts/grounding-v5-d58-review-corrections-v2/power-report-binding.json',
'44':'artifacts/grounding-v5-d58-haiku-successor/analysis.json',
'46':'artifacts/grounding-v5-d59-freeze/task-manifest.json',
'48':'artifacts/grounding-v5-d59-haiku-freeze/execution-plan.json',
'49':'artifacts/grounding-v5-d59-haiku-api-retry-successor/execution-plan.json',
'50':'artifacts/grounding-v5-d59-haiku-network-retry/execution-plan.json'}
def git(*args):return subprocess.check_output(['git',*args],cwd=ROOT)
def sha(body):return 'sha256:'+hashlib.sha256(body).hexdigest()
def normalize(tree):
 for node in ast.walk(tree):
  if isinstance(node,(ast.Module,ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef)) and node.body and isinstance(node.body[0],ast.Expr) and isinstance(node.body[0].value,ast.Constant) and isinstance(node.body[0].value.value,str):node.body.pop(0)
 return ast.dump(tree,include_attributes=False)
results={}
for num,path in CASE_PATHS.items():
 tree=OUT/('tree-'+num);data=json.loads((tree/path).read_text())
 bindings=data if num=='27' else (data['source_file_digests'] if num in ['42','43','44'] else data['source_binding']['files'])
 rows=[]
 for name,expected in bindings.items():
  historical=(tree/name).read_bytes(); recorded=(OUT/'tree-recorded-head'/name).read_bytes()
  row={'path':name,'expected_sha256':expected,'historical_sha256':sha(historical),'recorded_head_sha256':sha(recorded)}
  if historical!=recorded:
   if name.endswith('.py'):
    row['ast_equal_ignoring_docstrings']=normalize(ast.parse(historical))==normalize(ast.parse(recorded))
   rev=next(c[1] for c in CASES if c[0]==num)
   row['change_commits']=git('log','--format=%H %s',rev+'..b0f00f8','--',name).decode().splitlines()
  rows.append(row)
 results[num]={'artifact_path':path,'source_files':rows,'historical_bound_file_count':len(rows),'historical_binding_mismatches':[r['path'] for r in rows if r['historical_sha256']!=r['expected_sha256']]}
results['frozen_artifact_changes_since_evidence_revision']=git('diff','--name-only','b0f00f8','HEAD','--',*[CASE_PATHS[n] for n in CASE_PATHS]).decode().splitlines()
(OUT/'source-audit.json').write_text(json.dumps(results,indent=2,sort_keys=True)+'\n')
for n,d in results.items():
 if isinstance(d,dict):print(n,'bound files',d['historical_bound_file_count'],'mismatches',d['historical_binding_mismatches'], 'changed',[(r['path'],r.get('ast_equal_ignoring_docstrings')) for r in d['source_files'] if r['historical_sha256']!=r['recorded_head_sha256']])
